def find_nth_good_integer(N: int) -> int:
    digits = []
    N -= 1
    while N > 0:
        remainder = N % 5
        even_digit = remainder * 2
        digits.append(even_digit)
        N //= 5
    if not digits:
        digits.append(0)
    digits.reverse()
    return int(''.join(map(str, digits)))
